-- One-time import of legacy MariaDB data (dpoker_backup.sql) into the Supabase schema.
-- Run this once, after 0001_init.sql, against empty tables.
-- Skipped 24 orphaned game_player rows from the source dump whose game_id
-- had no matching row in `game` (games 148, 170, 174 were already gone upstream).




-- Advance identity sequences past the imported ids so new rows don't collide.
select setval(pg_get_serial_sequence('public.players', 'id'), (select max(id) from public.players));
select setval(pg_get_serial_sequence('public.games', 'id'), (select max(id) from public.games));
select setval(pg_get_serial_sequence('public.game_players', 'id'), (select max(id) from public.game_players));
